class TwoSum {
  public boolean solve(int[] arr) {
    int l = 0, r = arr.length - 1;
    while (l < r) {
      if (arr[l] + arr[r] > 0) {
        r--;
      } else if (arr[l] + arr[r] < 0) {
        l++;
      } else {
        return true;
      }
    }
    return false;
  }
}

